/// Seeds all static database tables atomically.
Future<void> seedStaticDatabaseContent(AppDatabase db) async {
  await db.batch((batch) {
    batch.insertAllOnConflictUpdate(db.namesOfAllahEntries, staticNamesOfAllahSeeds);
    batch.insertAllOnConflictUpdate(db.hadithNawawiEntries, staticHadithNawawiSeeds);
    batch.insertAllOnConflictUpdate(db.hisnContentCache, staticHisnCategorySeeds);
    batch.insertAllOnConflictUpdate(db.hisnContentItemCache, staticHisnItemSeeds);
  });
}
